SELECT
	COUNT(*)
FROM
	MARATHON_RECORD
WHERE
	homepage_id = #{homepage_id}
AND	contest_idx = #{contest_idx}
AND	contest_type_idx = #{contest_type_idx}
AND	applicant_idx = #{applicant_idx}

AND	book_name LIKE '%${search_text}%'


AND	book_journals LIKE '%${search_text}%'

SELECT
	homepage_id, contest_idx, contest_type_idx, applicant_idx, record_idx,
	member_id, member_name, book_name, read_page_count, book_resources,
	book_get_date, book_type, book_author, publisher, book_journals,
	record_date, modify_date, modify_id, call_no, reg_no, loan_choice
FROM
	MARATHON_RECORD
WHERE
	homepage_id = #{homepage_id}
AND	contest_idx = #{contest_idx}
AND	contest_type_idx = #{contest_type_idx}
AND	applicant_idx = #{applicant_idx}
AND	record_idx = #{record_idx}

SELECT
	SUM(read_page_count)
FROM
	MARATHON_RECORD
WHERE
	homepage_id = #{homepage_id}
AND	contest_idx = #{contest_idx}
AND	member_id = #{member_id}

SELECT B.applicant_idx, B.member_id, B.member_name, A.school_name, A.school_class, A.contest_type, C.page_count, B.read_page_count, A.read_page_count_total, A.finish_date, B.book_name, B.book_author, B.book_type, B.publisher, B.record_date, B.book_resources, B.book_journals, B.loan_choice FROM MARATHON_APPLICANT A, MARATHON_RECORD B, MARATHON_CONTEST_TYPE C WHERE A.homepage_id = C.homepage_id AND A.homepage_id = B.homepage_id AND A.contest_idx = C.contest_idx AND A.contest_idx = B.contest_idx AND A.contest_type_idx = C.contest_type_idx AND B.contest_type_idx = C.contest_type_idx AND A.applicant_idx = B.applicant_idx AND B.homepage_id = #{homepage_id}
AND B.contest_idx = #{contest_idx}
AND B.contest_type_idx = #{contest_type_idx}
AND B.applicant_idx = #{applicant_idx}

SELECT B.applicant_idx, B.member_id, B.member_name, A.school_name, A.school_class, A.contest_type, C.page_count, B.read_page_count, A.read_page_count_total, A.finish_date, B.book_name, B.book_author, B.book_type, B.publisher, B.record_date, B.book_resources, B.book_journals, B.loan_choice FROM MARATHON_APPLICANT A, MARATHON_RECORD B, MARATHON_CONTEST_TYPE C WHERE A.homepage_id = B.homepage_id AND B.homepage_id = C.homepage_id AND A.contest_idx = B.contest_idx AND B.contest_idx = C.contest_idx AND A.contest_type_idx = B.contest_type_idx AND B.contest_type_idx = C.contest_type_idx AND A.applicant_idx = B.applicant_idx AND B.homepage_id = #{homepage_id}
AND B.contest_idx = #{contest_idx}
AND B.contest_type_idx = #{contest_type_idx}
AND A.process_status = 1

